def backfill_conversations(apps, schema_editor):
    """Move existing page chat messages into a team conversation and mark
    that history as read for the owner and every member (so old messages
    don't show up as a wall of unread badges after upgrading)."""
    ChatConversation = apps.get_model('tracker', 'ChatConversation')
    ChatMessage = apps.get_model('tracker', 'ChatMessage')
    ChatRead = apps.get_model('tracker', 'ChatRead')
    Membership = apps.get_model('tracker', 'Membership')

    for owner_id in ChatMessage.objects.values_list('page_owner_id', flat=True).distinct():
        conv = ChatConversation.objects.create(page_owner_id=owner_id, kind='page')
        ChatMessage.objects.filter(page_owner_id=owner_id, conversation__isnull=True).update(conversation=conv)
        max_id = ChatMessage.objects.filter(conversation=conv).order_by('-id').values_list('id', flat=True).first() or 0
        ChatRead.objects.get_or_create(conversation=conv, user_id=owner_id,
                                       defaults={'last_read_id': max_id})
        for m in Membership.objects.filter(owner_id=owner_id):
            ChatRead.objects.get_or_create(conversation=conv, user_id=m.member_id,
                                           defaults={'last_read_id': max_id})


